  MenuItem as AriaMenuItem,
  composeRenderProps,
  type MenuItemProps,
  type MenuProps,
  MenuTrigger,
  Separator,
  type SeparatorProps,
} from "react-aria-components";
import { cn } from "./utils";
import { Popover } from "./popover";

export { MenuTrigger };

